// Generated by /ship test coverage audit (pass 1).
// Value: protects=a draft whose history has an op that won't replay opens read-only with the damaged notice, and "Keep the readable text" makes it writable again;
//   fails_when=DamagedDraftError stops reaching the notice, the repair's clearHistory call breaks, or the remount after repair stays read-only;
//   why_new=unit tests cover DamagedDraftError and loadDraft only; no test drives the damaged notice or its repair button; seam=none;
//   no_claim=how real corruption arises (the bad op is injected straight into IndexedDB)
import { expect, test } from '@playwright/test';
import { settle, startWriting, write } from './helpers';

test('a damaged history opens read-only and "Keep the readable text" repairs it', async ({ page }) => {
  const editor = await startWriting(page);
  await write(page, editor, 'readable text');
  await settle(page);

  // append an op whose runs don't cover the document, as a corrupt log would
  await page.evaluate(async () => {
    const db = await new Promise<IDBDatabase>((r) => {
      const q = indexedDB.open('kansowriter');
      q.onsuccess = () => r(q.result);
    });
    await new Promise<void>((resolve, reject) => {
      const t = db.transaction(['drafts', 'ops'], 'readwrite');
      const drafts = t.objectStore('drafts');
      const all = drafts.getAll();
      all.onsuccess = () => {
        const rec = all.result[0];
        t.objectStore('ops').put({ draftId: rec.id, seq: rec.head, op: [0, 0, 9999, 'x'] });
        drafts.put({ ...rec, head: rec.head + 1 });
      };
      t.oncomplete = () => resolve();
      t.onerror = () => reject(t.error);
    });
    db.close();
  });
  await page.reload();

  const draft = page.getByRole('textbox', { name: 'Draft' });
  await expect(page.getByText('Part of this draft’s history is damaged.')).toBeVisible();
  await expect(draft).toHaveAttribute('contenteditable', 'false');
  await expect(draft).toContainText('readable text');

  await page.getByRole('button', { name: 'Keep the readable text' }).click();
  await expect(page.getByText('Part of this draft’s history is damaged.')).toHaveCount(0);
  await expect(draft).toHaveAttribute('contenteditable', 'true');
  await draft.click();
  await page.keyboard.press('End');
  await draft.pressSequentially(' again');
  await settle(page);
  await page.reload();
  await expect(page.getByRole('textbox', { name: 'Draft' })).toContainText('readable text again');
  await expect(page.getByText('Part of this draft’s history is damaged.')).toHaveCount(0);
});
